<?php declare(strict_types=1); namespace Codejitsu\Ai\Console;
use Codejitsu\Ai\Tools\InteractiveToolApproval; use Codejitsu\Ai\Vessels\VesselRunner; use Codejitsu\Scrolls\ScrollCodex;
final readonly class AiTui { public function __construct(private VesselRunner $runner,private ScrollCodex $codex){} public function run(ConversationIO $io):int{$rows=$this->codex->query(['type'=>'vessel']);$vessels=array_map(static fn($r)=>(string)$r->name,$rows);sort($vessels);if($vessels===[]){$io->write("No Vessel Scrolls found.\n");return 1;}$vessel=$io->select('Vessel',$vessels);$approval=new InteractiveToolApproval(fn($c)=>$io->confirmTool($c));try{$session=$this->runner->start($vessel,approval:$approval);}catch(\Throwable $e){$io->write('Error: '.$e->getMessage()."\n");return 1;}$io->write("AI session ready. Type /help for commands.\n");while(true){$input=trim($io->ask('> '));if($input==='')continue;if($input==='/exit')return 0;if($input==='/help'){$io->write("/clear /new /context /skills /tools /spark /vessel /exit\n");continue;}if($input==='/clear'){$session->clear();$io->write("History cleared.\n");continue;}if($input==='/new'){$session=$this->runner->start($vessel,approval:$approval);$io->write("New session.\n");continue;}$map=['/context'=>'contexts','/skills'=>'skills','/tools'=>'tools'];if(isset($map[$input])){$io->write(implode("\n",$session->metadata()[$map[$input]]??[])."\n");continue;}if($input==='/spark'){$io->write('Spark: '.($session->metadata()['spark']??'')."\n");continue;}if($input==='/vessel'){$io->write('Vessel: '.$vessel."\n");continue;}try{$io->write($session->send($input)->text."\n");}catch(\Throwable $e){$io->write('Error: '.$e->getMessage()."\n");}}} }
